begin isolation level repeatable read;
set local search_path=pg_catalog;set local lock_timeout='3s';set local statement_timeout='60s';
do $guard$begin
 if current_user<>'postgres' or current_setting('serviceos.release_target',true) is distinct from 'tgbnakbxwcqjeimygroz' or current_setting('serviceos.release_sha256',true) is distinct from 'd91fed0a03d16c39100f36aba12f5eb89651678e47b4649c4e97d5867a0a8ecc' then raise exception 'Exact card reader target/source/role required';end if;
if (select md5(pg_get_functiondef(p.oid))||'|'||pg_get_userbyid(p.proowner)||'|'||coalesce(p.proacl::text,'NULL') from pg_proc p where p.oid='public.learn_card_communications_read(uuid,uuid,uuid,uuid,uuid[])'::regprocedure) is distinct from 'fe5cb8bd96f3c5e4cc49141b5da2bda7|learn_card_communication_reader|{learn_card_communication_reader=X/learn_card_communication_reader,authenticated=X/learn_card_communication_reader}' then raise exception 'Reader release function/access differs';end if;
if (select md5(pg_get_functiondef(p.oid))||'|'||pg_get_userbyid(p.proowner)||'|'||coalesce(p.proacl::text,'NULL') from pg_proc p where p.oid='public.learn_card_slack_job_context(uuid,uuid,uuid)'::regprocedure) is distinct from '2adbf3b163734e7a92efff84ae140b94|postgres|{postgres=X/postgres,learn_card_communication_reader=X/postgres}' then raise exception 'Reader release function/access differs';end if;
if (select md5(pg_get_functiondef(p.oid))||'|'||pg_get_userbyid(p.proowner)||'|'||coalesce(p.proacl::text,'NULL') from pg_proc p where p.oid='public.learn_interaction_is_draft(uuid,text,uuid)'::regprocedure) is distinct from '11d773ec2d8fe65321eda8f1a0bbd3da|postgres|{postgres=X/postgres,learn_card_communication_reader=X/postgres}' then raise exception 'Reader release function/access differs';end if;
 if exists(select 1 from pg_auth_members where roleid=(select oid from pg_roles where rolname='learn_card_communication_reader') and grantor=(select oid from pg_roles where rolname='postgres')) then raise exception 'Unexpected reader deploy membership';end if;
end $guard$;
create function pg_temp.reader_data() returns jsonb language sql as $data$select jsonb_build_object('jobs',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.jobs x)s),'sites',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.sites x)s),'people',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.people x)s),'companies',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.companies x)s),'customer_cards',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.customer_cards x)s),'contact_points',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.contact_points x)s),'learn_business_input_links',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.learn_business_input_links x)s),'learn_business_input_versions',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.learn_business_input_versions x)s),'learn_business_input_pages',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.learn_business_input_pages x)s),'learn_business_input_observations',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.learn_business_input_observations x)s),'slack_messages',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.slack_messages x)s),'slack_message_versions',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.slack_message_versions x)s),'interactions',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.interactions x)s),'profiles',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.profiles x)s),'platform_authority_grants',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.platform_authority_grants x)s),'provider_connections',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.provider_connections x)s),'email_messages',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.email_messages x)s),'phone_calls',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.phone_calls x)s),'phone_recordings',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.phone_recordings x)s),'receptionist_voicemails',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.receptionist_voicemails x)s),'receptionist_voicemail_intakes',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.receptionist_voicemail_intakes x)s),'receptionist_voicemail_sources',(select jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(x)::text)h from public.receptionist_voicemail_sources x)s))$data$;
create function pg_temp.reader_access() returns jsonb language sql as $access$select jsonb_build_object('memberships',(select coalesce(jsonb_agg(to_jsonb(x) order by roleid,member,grantor),'[]') from pg_auth_members x),'tables',(select md5(jsonb_agg(jsonb_build_array(c.relname,c.relowner,c.relacl,c.relrowsecurity) order by c.relname)::text) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),'policies',(select md5(jsonb_agg(to_jsonb(x) order by schemaname,tablename,policyname)::text) from pg_policies x),'cron',(select md5(jsonb_agg(to_jsonb(x) order by jobid)::text) from cron.job x))$access$;
create temp table reader_preservation on commit drop as select pg_temp.reader_data() data,pg_temp.reader_access() access;
grant learn_card_communication_reader to postgres with admin false,inherit true,set false granted by postgres;

-- Restrict draft/source inspection to linked interaction candidates. Keep the
-- existing role, tenant, visibility, status, excerpt and row-limit checks.
-- No rows or access grants change; CREATE OR REPLACE retains ownership and ACLs.
do $patch$ declare d text;needle text;replacement text;begin
 d:=pg_get_functiondef('public.learn_card_communications_read(uuid,uuid,uuid,uuid,uuid[])'::regprocedure);
 needle:=$old$ select coalesce(jsonb_agg(to_jsonb(s) order by s.occurred_at desc nulls last,s.id),'[]'::jsonb) into result from ($old$;
 replacement:=$new$ with job_context as materialized (
  select * from public.learn_card_slack_job_context(p_tenant,p_person,p_company)
 ), candidate_ids as materialized (
  select i.id from public.interactions i where i.tenant_id=p_tenant and
   (i.related_person_id=p_person or i.related_company_id=p_company or i.related_job_id=p_job or i.id=any(p_ids))
  union
  select jc.interaction_id from job_context jc
 )
 select coalesce(jsonb_agg(to_jsonb(s) order by s.occurred_at desc nulls last,s.id),'[]'::jsonb) into result from ($new$;
 if length(d)-length(replace(d,needle,''))<>length(needle) then raise exception 'Card communication aggregate baseline differs';end if;
 d:=replace(d,needle,replacement);
 needle:=$old$from public.interactions i left join public.learn_card_slack_job_context(p_tenant,p_person,p_company) jc on jc.interaction_id=i.id where$old$;
 replacement:=$new$from candidate_ids candidate join public.interactions i on i.id=candidate.id and i.tenant_id=p_tenant left join job_context jc on jc.interaction_id=i.id where$new$;
 if length(d)-length(replace(d,needle,''))<>length(needle) then raise exception 'Card communication join baseline differs';end if;
 execute replace(d,needle,replacement);
end $patch$;

revoke learn_card_communication_reader from postgres granted by postgres;
do $verify$begin
if (select md5(pg_get_functiondef(p.oid))||'|'||pg_get_userbyid(p.proowner)||'|'||coalesce(p.proacl::text,'NULL') from pg_proc p where p.oid='public.learn_card_communications_read(uuid,uuid,uuid,uuid,uuid[])'::regprocedure) is distinct from 'fe07b1ae36b8daebae5ffe89352ada18|learn_card_communication_reader|{learn_card_communication_reader=X/learn_card_communication_reader,authenticated=X/learn_card_communication_reader}' then raise exception 'Reader release function/access differs';end if;
if (select md5(pg_get_functiondef(p.oid))||'|'||pg_get_userbyid(p.proowner)||'|'||coalesce(p.proacl::text,'NULL') from pg_proc p where p.oid='public.learn_card_slack_job_context(uuid,uuid,uuid)'::regprocedure) is distinct from '2adbf3b163734e7a92efff84ae140b94|postgres|{postgres=X/postgres,learn_card_communication_reader=X/postgres}' then raise exception 'Reader release function/access differs';end if;
if (select md5(pg_get_functiondef(p.oid))||'|'||pg_get_userbyid(p.proowner)||'|'||coalesce(p.proacl::text,'NULL') from pg_proc p where p.oid='public.learn_interaction_is_draft(uuid,text,uuid)'::regprocedure) is distinct from '11d773ec2d8fe65321eda8f1a0bbd3da|postgres|{postgres=X/postgres,learn_card_communication_reader=X/postgres}' then raise exception 'Reader release function/access differs';end if;
 if (select data from reader_preservation) is distinct from pg_temp.reader_data() then raise exception 'Reader release changed retained data';end if;
 if (select access from reader_preservation) is distinct from pg_temp.reader_access() then raise exception 'Reader release changed access/schedules';end if;
end $verify$;
select jsonb_build_object('verifiedAt',clock_timestamp(),'data',(select data from reader_preservation),'accessAndSchedulesPreserved',true,'functionVerified',true) evidence;
commit;
